import { tv, type VariantProps } from "tailwind-variants";

const checkbox = tv({
  slots: {
    root: [
      "m-1 flex shrink-0 items-center justify-center rounded-sm border border-input bg-background shadow-md transition-all duration-150 ease-default outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring",
      "data-checked:bg-primary data-checked:text-primary-foreground",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive",
      "focus-visible:data-invalid:ring-destructive",
      "data-readonly:pointer-events-none data-readonly:opacity-60",
      "dark:bg-input/15",
      "dark:data-checked:bg-primary dark:data-checked:text-primary-foreground",
    ],
    indicator: [
      "flex items-center justify-center transition-[scale,opacity] duration-300 ease-default",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
      "data-unchecked:hidden",
      "[&>svg]:shrink-0",
    ],
  },
  variants: {
    size: {
      lg: {
        root: "size-5",
        indicator: "[&>svg:not([class*='size-'])]:size-4",
      },
      md: {
        root: "size-4.5",
        indicator: "[&>svg:not([class*='size-'])]:size-3.5",
      },
      sm: {
        root: "size-4",
        indicator: "[&>svg:not([class*='size-'])]:size-3",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

type CheckboxVariantProps = VariantProps<typeof checkbox>;

export { checkbox };
export type { CheckboxVariantProps };

"use client";

import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { CheckIcon, MinusIcon } from "lucide-react";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { checkbox, type CheckboxVariantProps } from "./checkbox.style";

type CheckboxContext = CheckboxVariantProps;

const CheckboxContext = createContext<CheckboxContext>({
  size: "md",
});

function useCheckbox() {
  return useContext(CheckboxContext);
}

function Checkbox({
  size,
  className,
  children,
  ...props
}: BaseCheckbox.Root.Props & CheckboxVariantProps) {
  return (
    <CheckboxContext.Provider value={{ size }}>
      <BaseCheckbox.Root
        data-slot="checkbox"
        className={mergeSlotClassName(checkbox({ size }).root, className)}
        {...props}
      >
        {children}
      </BaseCheckbox.Root>
    </CheckboxContext.Provider>
  );
}

function CheckboxIndicator({
  className,
  render,
  ...props
}: BaseCheckbox.Indicator.Props) {
  const { size } = useCheckbox();

  return (
    <BaseCheckbox.Indicator
      data-slot="checkbox-indicator"
      className={mergeSlotClassName(checkbox({ size }).indicator, className)}
      render={
        render !== undefined
          ? render
          : (indicatorProps, state) => (
              <span {...indicatorProps}>
                {state.indeterminate ? <MinusIcon /> : <CheckIcon />}
              </span>
            )
      }
      {...props}
    />
  );
}

export { Checkbox, CheckboxIndicator };
